        results = validate_all_policies()

        def _value_matches_type(value: Any, ptype: str) -> bool:
            if ptype == "bool":
                return isinstance(value, bool)
            if ptype == "int":
                return isinstance(value, int) and not isinstance(value, bool)
            if ptype == "float":
                return isinstance(value, (int, float)) and not isinstance(value, bool)
            if ptype in ("string", "enum"):
                return isinstance(value, str)
            return False

        layer_rank = {name: i for i, name in enumerate(LAYER_ORDER)}
        file_checks = [("universal", "universal", REGISTRY_DIR / "universal.toml")]
        if (REGISTRY_DIR / "domains").exists():
            file_checks.extend(
                (f"domain/{p.stem}", "domain", p)
                for p in sorted((REGISTRY_DIR / "domains").glob("*.toml"))
            )
        if (REGISTRY_DIR / "tasks").exists():
            file_checks.extend(
                (f"task/{p.stem}", "task", p)
                for p in sorted((REGISTRY_DIR / "tasks").glob("*.toml"))
            )
        if (REGISTRY_DIR / "models").exists():
            file_checks.extend(
                (f"model/{p.stem}", "model", p)
                for p in sorted((REGISTRY_DIR / "models").glob("*.toml"))
            )

        for name, layer, path in file_checks:
            if not path.exists():
                continue
            try:
                flat = _flatten_dict(_load_toml(path))
            except Exception as e:
                results[name] = str(e)
                continue

            schema_errors: List[str] = []
            for dp, value in flat.items():
                defn = self._schema.get(dp)
                if defn is None:
                    schema_errors.append(f"{dp}: not declared in schema")
                    continue
                if layer_rank[layer] < layer_rank[defn.min_layer]:
                    schema_errors.append(
                        f"{dp}: defined in {layer}, minimum layer is {defn.min_layer}"
                    )
                    continue
                if not _value_matches_type(value, defn.type):
                    schema_errors.append(
                        f"{dp}: got {value!r} (type {type(value).__name__}), expected {defn.type}"
