            if schema_errors:
                results[name] = "Schema validation errors:\n" + "\n".join(f"  {e}" for e in schema_errors)

        domains = sorted({v for v in DOMAIN_MAP.values() if (REGISTRY_DIR / "domains" / f"{v}.toml").exists()})
